using System;using System.IO;using System.Linq;using System.Collections;using UnityEngine;using UnityEngine.AI;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;
namespace DeliveryService.Mok.Editor {
public static class MechanicCheck {
 static string log;static void Check(bool ok,string text){log+=(ok?"PASS ":"FAIL ")+text+"\n";File.WriteAllText("Logs/Mechanic-check.txt",log);if(!ok)throw new Exception("Mechanic: "+text);}
 static IEnumerator Wait(float t){float until=Time.time+t;while(Time.time<until)yield return null;}
 static IEnumerator Key(Key key){InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState(key));yield return null;yield return null;InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());yield return null;}
 static void Place(PlayerCombat p,Vector3 at){var cc=p.GetComponent<CharacterController>();cc.enabled=false;p.transform.position=at+Vector3.up*(cc.height*.5f-cc.center.y+.12f);cc.enabled=true;Physics.SyncTransforms();}
 static IEnumerator Walk(PlayerCombat p,Vector3 at){var path=new NavMeshPath();Check(NavMesh.CalculatePath(p.transform.position,at,NavMesh.AllAreas,path)&&path.status==NavMeshPathStatus.PathComplete,"connected walking route");var cc=p.GetComponent<CharacterController>();foreach(var corner in path.corners.Skip(1)){float end=Time.time+45;while(Vector2.Distance(new(p.transform.position.x,p.transform.position.z),new(corner.x,corner.z))>.35f){if(Time.time>end)throw new Exception("blocked "+p.transform.position+" -> "+corner);var d=corner-p.transform.position;d.y=0;p.View.transform.rotation=Quaternion.LookRotation(d);cc.Move((d.normalized*6+Vector3.down*3)*Time.deltaTime);yield return null;}}}
 public static IEnumerator Verify(bool isolated=false){log="Mechanic mission chain\n";yield return Wait(.5f);var m=MechanicMission.Current;Check(m&&m.supportVehicle&&m.rendezvous,"saved actor props and support car");Check(!m.Begin(),"locked before backdoor completion");if(isolated){typeof(BrokerMission).GetProperty("State").SetValue(m.preparation.delivery.broker,BrokerMission.Phase.Complete);typeof(SpecialOrderMission).GetProperty("State").SetValue(m.preparation.delivery,SpecialOrderMission.Phase.Complete);typeof(BackdoorMission).GetProperty("State").SetValue(m.preparation,BackdoorMission.Phase.Complete);m.preparation.delivery.broker.day.EnterNightPreparation();StoryPhoneInbox.Current.AutoOpenEnabled=false;}else yield return BackdoorCheck.Verify(true);
  var b=m.preparation.delivery.broker;var p=m.Player;var app=UnityEngine.Object.FindFirstObjectByType<StoryPhoneApp>(FindObjectsInactive.Include);app.Open(false);app.Move(3);app.Confirm();app.Refresh();Check(app.action.text=="미션 시작","backdoor completion unlocks phone mission");app.Confirm();yield return null;Check(m.State==MechanicMission.Phase.Meet,"phone starts mechanic mission");b.day.OnClick_ConfirmClose();Check(!b.day.IsTransitioning,"mission blocks settlement");
  var move=p.GetComponent<PlayerMove>();move.enabled=false;var look=p.View.GetComponent<CameraMove>();look.enabled=false;Place(p,m.approach.position);p.View.transform.LookAt(m.mechanic.position+Vector3.up*1.2f);yield return Wait(.2f);yield return Key(UnityEngine.InputSystem.Key.F);Check(m.State==MechanicMission.Phase.Briefing,"F starts mechanic briefing");BrokerMissionCheck.Capture(b,"Mechanic-meeting");Time.timeScale=0;m.AdvanceDialogue(true);Check(m.State==MechanicMission.Phase.Briefing,"pause preserves briefing");Time.timeScale=1;yield return Key(UnityEngine.InputSystem.Key.Space);Check(m.State==MechanicMission.Phase.Retrieve&&m.Pursuers.Length==2,"skip gives control with two mission opponents");
  foreach(var enemy in m.Pursuers)enemy.ExternalAttackControl=true;yield return Walk(p,m.pickupStand.position);p.View.transform.LookAt(m.parts.transform.position);yield return Wait(.4f);Check(m.Pursuers.All(e=>e.IsAggressive),"approaching parts activates pursuit");foreach(var enemy in m.Pursuers)enemy.gameObject.SetActive(false);yield return Key(UnityEngine.InputSystem.Key.F);Check(m.PartRecovered&&m.State==MechanicMission.Phase.Return,"physical F recovers mission part");yield return null;Check(Vector3.Distance(m.parts.transform.position,p.View.transform.position)<1.5f,"carried part appears with player");BrokerMissionCheck.Capture(b,"Mechanic-recovered");m.Cancel();Check(!m.VehicleSupportUnlocked&&m.PartRecovered&&m.Pursuers.Length==0,"cancel preserves part and cleans opponents without reward");Check(m.Begin()&&m.State==MechanicMission.Phase.Return,"retry resumes return with recovered part");look.enabled=false;
  yield return Walk(p,m.approach.position);p.View.transform.LookAt(m.mechanic.position+Vector3.up*1.2f);yield return Wait(.2f);yield return Key(UnityEngine.InputSystem.Key.F);if(m.State!=MechanicMission.Phase.Handover){var d=m.mechanic.position+Vector3.up*1.1f-p.View.transform.position;log+="return diagnostic state="+m.State+" position="+p.transform.position+" mechanic="+m.mechanic.position+" canAct="+p.CanAct+" hits="+string.Join(";",Physics.RaycastAll(p.View.transform.position,d.normalized,d.magnitude,~0,QueryTriggerInteraction.Ignore).Select(h=>h.collider.name))+"\n";}Check(m.State==MechanicMission.Phase.Handover,"F hands part to mechanic");yield return Wait(m.handoverSeconds+.2f);Check(m.State==MechanicMission.Phase.Debrief&&m.keys.activeSelf&&Vector3.Distance(m.parts.transform.position,m.benchRest.position)<.05f,"physical handover reaches workbench and shows key");BrokerMissionCheck.Capture(b,"Mechanic-support");int money=MoneyManager.Instance.currentMoney;yield return Key(UnityEngine.InputSystem.Key.Space);Check(m.Completed&&m.VehicleSupportUnlocked&&!m.Begin()&&!MechanicMission.Active,"vehicle support awarded once");Check(MoneyManager.Instance.currentMoney==money,"support does not modify cash");app.Open(false);app.Move(3);app.Confirm();app.Refresh();Check(app.action.text.Contains("지원 확보 완료"),"phone displays vehicle support");b.day.currentDay++;yield return null;Check(m.VehicleSupportUnlocked,"vehicle support survives day change");app.gameObject.SetActive(false);look.enabled=true;move.enabled=true;
 }
}
}
#endif
